Certainly! In Flutter, you can limit the number of items displayed per row using a `Wrap` widget or by customizing the `GridView` widget. Below are examples of both approaches.

### Using Wrap Widget

The `Wrap` widget is perfect for displaying items in rows and wrapping them to the next line when they exceed the available width.

```dart
import 'package:flutter/material.dart';

void main() {
  runApp(MyApp());
}

class MyApp extends StatelessWidget {
  @override
  Widget build(BuildContext context) {
    return MaterialApp(
      home: Scaffold(
        appBar: AppBar(
          title: Text('Wrap Example'),
        ),
        body: ItemList(),
      ),
    );
  }
}

class ItemList extends StatelessWidget {
  final int itemsPerRow = 3; // Limit the number of items per row

  @override
  Widget build(BuildContext context) {
    return Wrap(
      spacing: 8.0, // space between widgets
      runSpacing: 8.0, // space between rows
      children: List.generate(
        20, // Total number of items
        (index) => Container(
          width: (MediaQuery.of(context).size.width / itemsPerRow) - 16,
          height: 50,
          color: Colors.blue[100 * (index % 9)],
          child: Center(
            child: Text(
              'Item ${index + 1}',
              style: TextStyle(fontSize: 16),
            ),
          ),
        ),
      ),
    );
  }
}
```

### Using GridView Widget

If you want more control over the layout and need to handle resizing better, you can use the `GridView` widget with a `SliverGridDelegateWithMaxCrossAxisExtent`.

```dart
import 'package:flutter/material.dart';

void main() {
  runApp(MyApp());
}

class MyApp extends StatelessWidget {
  @override
  Widget build(BuildContext context) {
    return MaterialApp(
      home: Scaffold(
        appBar: AppBar(
          title: Text('GridView Example'),
        ),
        body: ItemList(),
      ),
    );
  }
}

class ItemList extends StatelessWidget {
  final int itemsPerRow = 3; // Limit the number of items per row

  @override
  Widget build(BuildContext context) {
    double itemWidth = (MediaQuery.of(context).size.width / itemsPerRow) - 16;

    return GridView.builder(
      itemCount: 20, // Total number of items
      gridDelegate: SliverGridDelegateWithMaxCrossAxisExtent(
        maxCrossAxisExtent: itemWidth, // Maximum extent of each cross axis
        mainAxisSpacing: 8.0, // Space between rows
        crossAxisSpacing: 8.0, // Space between columns
        childAspectRatio: 1.0, // Aspect ratio of each item
      ),
      itemBuilder: (context, index) {
        return Container(
          width: itemWidth,
          height: itemWidth,
          color: Colors.blue[100 * (index % 9)],
          child: Center(
            child: Text(
              'Item ${index + 1}',
              style: TextStyle(fontSize: 16),
            ),
          ),
        );
      },
    );
  }
}
```

